    "Script": "MailManagement = {
    init: async function(app, container) {
        app = app || session.app;
        container = container || $(".component[name=MailManagement]");
        api.addToMetaCache([
			{
        "Name": "Core",
        "Types": [
            [meta[Core/QueuedEmail]],
            [meta[Core/SentEmail]],
            [meta[Core/MailServer]]
        ]
    }
		]);
        $("[name=tabs]", container).kendoTabStrip({
            animation: {
                open: {
                    effects: "fadeIn"
                }
            }
        });

        MailManagement.setupMailSentGrid(app, container);
        MailManagement.setupMailServerGrid(app, container);
        MailManagement.setupMailQueueGrid(app, container);
    },

    save: async function (e, grid) {
        e.preventDefault();
        var item = grid.dataItem($(e.currentTarget).closest("tr"));
        await item.save().then(notification.success("[resource_displayname[saved]]"));
        grid.refresh();
    },

    setupMailSentGrid: async function(app, container) {
        var mailSent = await model.getDatasource({
            endpoint: "Mail/SentEmail",
            odataAppend: "?$filter=AppId eq " + app.Id,
            sort: {
                field: "SentOn",
                dir: "desc"
            }
        });

        var mailSentGrid = new GridWidget($("[name=history]", container), mailSent);
        mailSentGrid.filterable = true;

        mailSentGrid.detailTemplate = "<iframe style='width:100%;height:600px;'></iframe>"
        mailSentGrid.detailExpand = function(e) {
            var item = mailSentGrid.dataItem($(e.masterRow));
            var element = $("iframe", $(e.detailRow))[0];
            var document = element.contentDocument || element.contentWindow.document;
            document.write(item.Content);
            document.close();
        };
        mailSentGrid.columns = [
            {
                field: "Subject",
                title: "[resource_displayname[subject]]"
            },
            {
                field: "From",
                title: "[resource_displayname[from]]"
            },
            {
                field: "SentByUserId",
                title: "[resource_displayname[sentbyuserid]]"
            },
            {
                field: "To",
                title: "[resource_displayname[to]]"
            },
            {
                field: "CC",
                title: "[resource_displayname[cc]]"
            },
            {
                field: "SentOn",
                title: "[resource_displayname[senton]]",
                type: "date",
                format: "{0: " + type.dateFormat + " HH:mm}"
            }
        ];
        mailSentGrid.init();
    },

    setupMailServerGrid: async function(app, container) {
        var mailServer = await model.getDatasource({
            endpoint: "Mail/MailServer",
            odataAppend: "?$filter=AppId eq " + app.Id
        });

        var mailServerGrid = new GridWidget($("[name=mailServer]", container), mailServer);
        mailServerGrid.filterable = true;
        mailServerGrid.editable = true;
        mailServerGrid.groupable = false;
        mailServerGrid.toolbar = "<button name='create'><span class='k-icon k-i-plus'></span>[resource_displayname[new]]</button>";
        mailServerGrid.columns = [
            {
                field: "Name",
                title: "[resource_displayname[name]]"
            },
            {
                field: "User",
                title: "[resource_displayname[user]]"
            },
            {
                field: "Password",
                title: "[resource_displayname[password]]",
                template: "#='*'.repeat(Password.length)#"
            },
            {
                field: "Host",
                title: "[resource_displayname[host]]"
            },
            {
                field: "Port",
                title: "[resource_displayname[port]]"
            },
            {
                field: "EnableSSL",
                title: "[resource_displayname[enablessl]]"
            },
        ];
        mailServerGrid.commands.push({
            name: "save",
            icon: "k-i-save",
            text: "[resource_displayname[save]]"
        });
        mailServerGrid.commands.push({
            name: "remove",
            icon: "k-i-delete",
            text: "[resource_displayname[remove]]"
        });
        mailServerGrid.dataBound = function (e) {
            $("[name=save]", mailServerGrid.gridElement)
                .off("click")
                .on("click", (e) => MailManagement.save(e, mailServerGrid));

            $("[name=remove]", mailServerGrid.gridElement)
                .off("click")
                .on("click", (e) => MailManagement.remove(e, mailServerGrid));

            $("button[name=create]", mailServerGrid.gridElement).on("click", (e) => MailManagement.newMailServer(e, mailServerGrid, app));
        };
        mailServerGrid.init();
    },

    setupMailQueueGrid: async function(app, container) {
        var mailQueue = await model.getDatasource({
            endpoint: "Mail/QueuedEmail",
            odataAppend: "?$filter=AppId eq " + app.Id + "&$expand=FailedSends"
        });

        var mailQueueGrid = new GridWidget($("[name=queue]", container), mailQueue);
        mailQueueGrid.filterable = true;
        mailQueueGrid.detailTemplate = $("[name=mailQueueExpand]").first().html();
        mailQueueGrid.detailExpand = function(e) {
            var item = mailQueueGrid.dataItem($(e.masterRow));
            $("[name=tabs]", $(e.detailRow)).kendoTabStrip({
                animation: {
                    open: {
                        effects: "fadeIn"
                    }
                }
            });

            var element = $("iframe", $(e.detailRow))[0];
            var document = element.contentDocument || element.contentWindow.document;
            document.write(item.Content);
            console.log(item.Content);
            document.close();

            var grid = new GridWidget($("[name=failuresTab]", $(e.detailRow)), {
                data: item.FailedSends,
                pageSize: 50,
                sort: {
                    field: "AttemptedOn",
                    dir: "desc"
                }
            });
            grid.filterable = false;
            grid.groupable = false;
            grid.columns = [
                {
                    field: "AttemptedOn",
                    type: "date",
                    format: "{0: " + type.dateFormat + "  HH:mm}",
                    title: "[resource_displayname[attemptedon]]"
                },
                {
                    field: "FailureReason",
                    title: "[resource_displayname[failurereason]]"
                },
            ];
            grid.init();
        };

        mailQueueGrid.dataBound = function() {
            $("[name=destroy]", mailQueueGrid.gridElement).on("click", async (e) => {
                var item = mailQueueGrid.dataItem($(e.currentTarget).closest("tr"));
                await api.destroy("Mail/QueuedEmail(" + item.Id + ")").then(() => {
                    notification.success("[resource_displayname[deleted]]");
                    mailQueueGrid.refresh();
                }).catch((err) => error(err));
            });
        };

        mailQueueGrid.commands.push({name: "destroy", icon: "k-i-delete", text: "[resource_displayname[delete]]"});
        mailQueueGrid.columns = [
            {
                field: "Subject",
                title: "[resource_displayname[subject]]"
            },
            {
                field: "SentByUserId",
                title: "[resource_displayname[sentbyuserid]]"
            },
            {
                field: "To",
                title: "[resource_displayname[to]]"
            },
            {
                field: "CC",
                title: "[resource_displayname[cc]]"
            },
        ];
        mailQueueGrid.init();
    },

    remove: async function (e, grid) {
        e.preventDefault();
        var item = grid.kendoObject.dataItem($(e.currentTarget).closest("tr"));
        await api.destroy("Mail/MailServer(" + item.Id + ")").then(async () => {
            notification.success("[resource_displayname[deleted]]");
            grid.refresh();
        }).catch((err) => error(err));
    },

    newMailServer: async function (e, grid, app) {
		e.preventDefault();
		var newMailServer = {
			Id: 0,
			AppId: app.Id,
			Name: "",
			User: "",
			Password: "",
			Host: "",
			Port: "",
            EnableSSL: true
		};
		var args = {
			fields: [
				{
                    field: "Name",
                    title: "[resource_displayname[name]]",
                    description: "[resource_description[name]]"
                }, 
				{
                    field: "User",
                    title: "[resource_displayname[user]]",
                    description: "[resource_description[user]]"
                }, 
				{
                    field: "Password",
                    title: "[resource_displayname[password]]",
                    description: "[resource_description[password]]"
                },
                {
                    field: "Host",
                    title: "[resource_displayname[host]]",
                    description: "[resource_description[host]]"
                }, 
                {
                    field: "Port",
                    title: "[resource_displayname[port]]",
                    description: "[resource_description[port]]"
                }, 
                {
                    field: "EnableSSL",
                    title: "[resource_displayname[enablessl]]",
                    description: "[resource_description[enablessl]]"
                }, 
			],
			title: "[resource_displayname[createnewmailserver]]",
			data: newMailServer,
			confirm: "[resource_displayname[confirm]]",
			close: "[resource_displayname[close]]"
		};
		var addMailServerDialog = new EditorDialog(args);
		addMailServerDialog.events.confirm = async function () {
			await api.add("Mail/MailServer", addMailServerDialog.data.toJSON()).then(() => {
				addMailServerDialog.events.close();
				notification.success("[resource_displayname[created]]");
				grid.refresh();
			}).catch((err) => error(err));
		};
		addMailServerDialog.init();
	},
}",
